using System;using System.IO;using System.Linq;using System.Runtime.InteropServices;using System.Collections.Generic;using System.Web.Script.Serialization;using interop.ICApiIronCAD;namespace RockPro{public static class LatchInProcess{static Dictionary<string,object> O(object x){return (Dictionary<string,object>)x;}static IZDoc D(object x){return x is IZDoc?(IZDoc)x:(IZDoc)Marshal.GetObjectForIUnknown(new IntPtr(Convert.ToInt64(x)));}public static int Run(string folder){var j=new JavaScriptSerializer{MaxJsonLength=64000000};var r=new Dictionary<string,object>();try{var q=O(j.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json"))));if(System.Diagnostics.Process.GetCurrentProcess().Id!=Convert.ToInt32(q["expected_pid"]))throw new Exception("Host changed");dynamic l=Marshal.GetActiveObject("IronCAD.Application");var app=(IZBaseApp)l.ZIronCADApp;var doc=((Array)app.GetAllOpenDocs()).Cast<object>().Select(D).Single(d=>d.Name==(string)q["output"]);var s=(IZSceneDoc)doc;var u=(IZSceneDocUtility)s;var m=O(j.DeserializeObject((string)s.GetTopElement().get_CustomPropMgr(false).GetValueByName("RockPro.MountCounts.v1")));var rows=((object[])m["rows"]).Select(O).ToArray();int index=0;var reports=new List<object>();foreach(var row in rows){int count=(int)s.ParameterMgr.GetParameterByName((string)row["count"]).Value;int expected=index++==0?Convert.ToInt32(q["first_count"]):count;if(count!=expected)throw new Exception("Unexpected UI value");int active=0;foreach(var slot in (object[])row["slots"]){var members=((object[])slot).Select(id=>u.GetElementById(Convert.ToInt32(id))).ToArray();bool suppressed=members[0].GetStateStatus(eZElementState.Z_SUPPRESSED);if(members.Any(e=>e.GetStateStatus(eZElementState.Z_SUPPRESSED)!=suppressed))throw new Exception("Hardware/cut desynchronization");if(!suppressed)active++;}if(count!=5&&active!=expected)throw new Exception("Autonomous count failed "+row["count"]+" expected "+expected+" active "+active);reports.Add(new{name=row["count"],requested=count,active=active});}r["rows"]=reports;r["status"]=s.ParameterMgr.GetParameterByName("RP_IloscOkuc_Status").TextParameterValue;r["manual_apply_calls"]=0;r["manual_load_calls"]=0;r["manual_start_calls"]=0;
if(q.ContainsKey("restore")&&(bool)q["restore"]){s.ParameterMgr.GetParameterByName("RP_UchwytyKorpusLewa_Liczba").Expression="3";s.Update();r["restore_requested"]=true;}if(q.ContainsKey("save")&&(bool)q["save"]){s.SaveAs((string)q["output"],eZLinksSaveOptions.Z_LINKS_COPY_ALL,false);s.ExportImage(Path.Combine(folder,"final.png"),eZImageFormat.Z_IMAGE_PNG,1500,1100,true);r["parameters"]=Enumerable.Range(0,s.ParameterMgr.Count).Select(i=>s.ParameterMgr.GetParameter(i)).Select(p=>new{name=p.Name,expression=p.Expression,value=p.Type==eZParamType.Z_PARAMETER_TYPE_TEXT?0:p.Value,notes=p.Notes}).ToArray();}r["passed"]=true;}catch(Exception ex){r["passed"]=false;r["error"]=ex.ToString();}File.WriteAllText(Path.Combine(folder,"result.json"),j.Serialize(r));return (bool)r["passed"]?0:1;}}}